#include "selftest.h"

#include <math.h>
#include <stdio.h>

#include "andon_test_vectors.h"  // generated by andon.export_c (not in git)
#include "logmel.h"
#include "model.h"
#include "model_params.h"

#define N_MELS ANDON_TV_N_MELS
#define FRAMES ANDON_TV_FRAMES

static float logmel_frames[FRAMES][N_MELS];  // the C front end's output for the test audio
static float frame_buf[LOGMEL_N_FFT];
static int8_t input_buf[MODEL_INPUT_MAX];

// np.pad(mode="reflect") of the test audio by n_fft / 2 at both ends, as Python frames it.
static float padded_sample(long j) {
    const long len = ANDON_TV_AUDIO_LEN;
    long i = j - LOGMEL_N_FFT / 2;
    if (i < 0) i = -i;
    if (i >= len) i = 2 * (len - 1) - i;
    return andon_tv_audio[i] / 32768.0f;
}

static void run_front_end(selftest_clock_fn now_us, selftest_result_t *r) {
    logmel_init();
    for (int f = 0; f < FRAMES; f++) {
        for (int i = 0; i < LOGMEL_N_FFT; i++) {
            frame_buf[i] = padded_sample((long)f * ANDON_TV_HOP_LENGTH + i);
        }
        const uint64_t t0 = now_us();
        logmel_frame(&andon_mel_bank, frame_buf, logmel_frames[f]);
        const uint64_t dt = now_us() - t0;
        r->logmel_us_total += dt;
        if (dt > r->logmel_us_max) r->logmel_us_max = dt;
        for (int m = 0; m < N_MELS; m++) {
            const float err = fabsf(logmel_frames[f][m] - andon_tv_logmel[f * N_MELS + m]);
            if (err > r->worst_logmel_db) r->worst_logmel_db = err;
        }
    }
    r->frames = FRAMES;
}

static float abs_err(float a, float b) { return fabsf(a - b); }

static void run_model(selftest_clock_fn now_us, selftest_result_t *r) {
    const model_t *m = &andon_model;
    const int patch_len = m->n_mels * m->patch_frames;
    int32_t acc[MODEL_MAX_CLASSES];
    float logits[MODEL_MAX_CLASSES];

    // 1. From Python's int8 input, every patch (the stress patch too): integers must match
    //    exactly, so only the float logits and score may differ.
    for (int k = 0; k < ANDON_TV_N; k++) {
        if (model_head_acc(m, &andon_tv_input[k * patch_len], acc, NULL) != 0) {
            r->head_mismatches += m->n_classes;
            continue;
        }
        for (int c = 0; c < m->n_classes; c++) {
            r->head_mismatches += acc[c] != andon_tv_head_acc[k * m->n_classes + c];
        }
        model_logits(m, acc, logits);
        const float err =
            abs_err(model_score(m->n_classes, logits, ANDON_TV_TRUE_ID), andon_tv_score[k]);
        if (!(err <= r->worst_score_err)) r->worst_score_err = err;  // NaN counts as worst
    }

    // 2. End to end, timed: the C log-mel frames of each audio patch, quantized by C.
    for (int k = 0; k < ANDON_TV_N_AUDIO; k++) {
        const float *patch = logmel_frames[k * ANDON_TV_PATCH_HOP];
        model_quantize_input(m, patch, input_buf);
        for (int i = 0; i < patch_len; i++) {
            r->input_diffs += input_buf[i] != andon_tv_input[k * patch_len + i];
        }
        r->input_values += patch_len;

        const uint64_t t0 = now_us();
        const float score = model_score_patch(m, patch, ANDON_TV_TRUE_ID);
        const uint64_t dt = now_us() - t0;
        r->model_us_total += dt;
        if (dt > r->model_us_max) r->model_us_max = dt;
        const float err = abs_err(score, andon_tv_score[k]);
        if (!(err <= r->worst_e2e_score_err)) r->worst_e2e_score_err = err;
    }
    r->patches = ANDON_TV_N_AUDIO;
}

int selftest_run(selftest_clock_fn now_us, selftest_result_t *r) {
    *r = (selftest_result_t){0};
    run_front_end(now_us, r);
    run_model(now_us, r);
    r->ram_bytes = logmel_ram_bytes() + model_ram_bytes() +
                   (uint32_t)(sizeof logmel_frames + sizeof frame_buf + sizeof input_buf);
    r->pass = r->worst_logmel_db <= SELFTEST_LOGMEL_TOL_DB && r->head_mismatches == 0 &&
              r->worst_score_err <= SELFTEST_SCORE_TOL &&
              r->worst_e2e_score_err <= SELFTEST_E2E_SCORE_TOL;
    return r->pass;
}

void selftest_print(const selftest_result_t *r) {
    const double frame_ms = r->frames ? r->logmel_us_total / 1000.0 / r->frames : 0.0;
    const double patch_ms = r->patches ? r->model_us_total / 1000.0 / r->patches : 0.0;
    // Real time: a new 32 ms frame arrives every hop, and a patch is scored every
    // ANDON_TV_PATCH_HOP frames, so the CNN's share per frame is patch time / hop.
    const double per_frame_ms = frame_ms + patch_ms / ANDON_TV_PATCH_HOP;
    const double budget_ms = 1000.0 * ANDON_TV_HOP_LENGTH / ANDON_TV_SAMPLE_RATE;
    printf("log-mel: %d frames, worst |C - Python| %.2e dB (tol %.0e), %.3f ms/frame avg,"
           " %.3f ms max\n",
           r->frames, (double)r->worst_logmel_db, (double)SELFTEST_LOGMEL_TOL_DB, frame_ms,
           r->logmel_us_max / 1000.0);
    printf("cnn: %d patches, head sum mismatches %d, worst score err %.2e (tol %.0e)\n",
           ANDON_TV_N, r->head_mismatches, (double)r->worst_score_err,
           (double)SELFTEST_SCORE_TOL);
    printf("end to end: %d patches, int8 input diffs %ld of %ld, worst score err %.2e"
           " (tol %.0e), %.2f ms/patch avg, %.2f ms max\n",
           r->patches, r->input_diffs, r->input_values, (double)r->worst_e2e_score_err,
           (double)SELFTEST_E2E_SCORE_TOL, patch_ms, r->model_us_max / 1000.0);
    printf("real time: %.3f ms of compute per %.0f ms of audio (%s)\n", per_frame_ms,
           budget_ms, per_frame_ms < budget_ms ? "fits" : "TOO SLOW");
    printf("static RAM: %lu bytes\n", (unsigned long)r->ram_bytes);
    printf("self-test: %s\n", r->pass ? "PASS" : "FAIL");
}
